mapper.select:

WHERE 1=1



    AND a.rbd = #{rbd}


    AND a.ensenanza = #{ensenanza}


    AND a.grado = #{grado}


    AND a.letra = #{letra}


    -- Ejemplo:
    -- AND EXTRACT(MONTH FROM a.asis_fecha_creacion) = #{mes}
    -- Ajusta según tu motor de DB (MySQL, Postgres, etc.)


    -- Ejemplo:
    -- AND EXTRACT(DAY FROM a.asis_fecha_creacion) = #{dia}


    AND a.rut = #{rut}


    AND a.asis_fecha_creacion >= CAST(#{periodoDesde} AS DATE)


    AND a.asis_fecha_creacion <= CAST(#{periodoHasta} AS DATE)


    AND a.establecimiento = #{establecimiento}


    AND a.region = #{region}


    AND a.provincia = #{provincia}


    AND a.comuna = #{comuna}



    ORDER BY ${orderBy} ${order}


    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(a.pk_asis_id_asistencia)
FROM asistencia a
WHERE 1=1


    AND a.rbd = #{rbd}


